export function normalizeRegisteredSubjectId(value) {
  return SUBJECT_IDENTIFIERS[String(value ?? "").trim().toLocaleLowerCase("ko-KR")] ?? "";
}

export function registeredSubjectName(value) {
  return SUBJECT_NAMES[normalizeRegisteredSubjectId(value)] ?? "";
}

export function contentScopeAllowsRegisteredSubject(scope, subject) {
  const courses = CONTENT_SCOPE_COURSES[String(scope)] ?? [];
  const subjectName = registeredSubjectName(subject);
  return Boolean(subjectName) && courses.length > 0 && courses.every((examType) => (
    EXAM_TYPE_SUBJECTS[examType]?.includes(subjectName)
  ));
}

export function contentScopeAllowsRegisteredSubjectId(scope, subjectId) {
  const courses = CONTENT_SCOPE_COURSES[String(scope)] ?? [];
  const normalizedSubjectId = normalizeRegisteredSubjectId(subjectId);
  return Boolean(normalizedSubjectId) && courses.length > 0 && courses.every((examType) => (
    EXAM_TYPE_SUBJECT_IDS[examType]?.includes(normalizedSubjectId)
  ));
}

export function normalizeRegisteredExamType(value) {
  const normalized = String(value ?? "").trim().toUpperCase();
  return REGISTERED_EXAM_TYPES.find((examType) => examType === normalized) ?? "";
}

export function normalizeRegisteredContentScope(value) {
  const scope = String(value ?? "").trim();
  const examType = normalizeRegisteredExamType(scope);
  return examType || CONTENT_SCOPE_ALIASES[scope.toUpperCase()] || scope;
}
